const errors = { UploadFailed }

/**
 * Attach a file to a message: store it with a task that reports its progress, then wait for
 * the user to confirm, showing how long they have waited.
 */
export const Attach = Roadbook.make<AttachDef>(ir, "Attach", errors)

// ---- machine: AttachMany ----

export const Add = Schema.TaggedStruct("Add", { file: File })
export type Add = typeof Add.Type

export const Cancel = Schema.TaggedStruct("Cancel", { name: Schema.String })
export type Cancel = typeof Cancel.Type

export const Done = Schema.TaggedStruct("Done", {})
export type Done = typeof Done.Type

export interface AttachManyDef extends Roadbook.MachineDef {
  readonly name: "AttachMany"
  readonly input: {}
  readonly output: number
  readonly error: never
  readonly event: Add | Cancel | Done
  readonly emits: never
  readonly state: "AttachMany" | "AttachMany.Open" | "AttachMany.Closed"
  readonly fns: {}
  readonly actions: {
    readonly showFileProgress: { readonly name: string; readonly percent: number }
  }
  readonly tasks: {
    readonly storeFile: {
      readonly args: { readonly file: File }
      readonly success: Url
      readonly error: UploadFailed
      readonly emits: Progress | Retrying
    }
  }
  readonly machines: {}
}

/**
 * Attach several files at once: one `storeFile` task per file, keyed by the file's name, in a
 * collection of tasks. Counts the files stored.
 */
export const AttachMany = Roadbook.make<AttachManyDef>(ir, "AttachMany", errors)
